/* Yousj OS - interrupt/exception entry stubs (M2).
 * Written by Muse (coordinator).
 *
 * Exception stubs 0..31 each push their vector number and jump to
 * exc_common, which hands the stack pointer to exception_handler()
 * (it dumps over serial and halts, so no register saving is needed
 * here -- this path never returns).
 *
 * exc_table (in .rodata) collects the 32 stub addresses for the C
 * side to install into the IDT; both the stubs and the table are
 * generated by the same macro so they can never drift apart.
 *
 * irq0_stub is the timer entry: it saves the caller-saved set (the
 * C handler and anything it calls, including the scheduler, follow
 * the SysV convention for the rest), calls irq0_handler(), then
 * restores and iretq's. Register push count is 9: together with
 * the 5-word hardware frame this keeps the C call stack-aligned.
 * Preemption works because context_switch() inside the handler
 * swaps to another task's stack mid-handler; the interrupted task
 * later resumes right here and unwinds through the pops + iretq.
 */

    .altmacro

    .section .text
    .macro EXC_STUB i
    .globl exc_stub_\i
exc_stub_\i:
    push $\i
    jmp exc_common
    .endm

    .set i, 0
    .rept 32
    EXC_STUB %i
    .set i, i+1
    .endr

exc_common:
    mov %rsp, %rdi
    call exception_handler
exc_hang:
    cli
    hlt
    jmp exc_hang

    /* Page-fault stub (M17): unlike the other exceptions,
     * #PF must be able to RETURN -- demand paging resolves
     * the fault and retries the access. Saves the caller-
     * saved set (the C handler follows SysV for the rest),
     * builds a yousj_pf_info on the stack, and calls
     * yousj_page_fault(), which returns only for resolved
     * faults. GS discipline mirrors irq0_stub: swap when the
     * interrupted frame is ring 3, swap back before iretq.
     * Hardware frame on entry: [rsp]=err, +8 RIP, +16 CS,
     * +24 RFLAGS, +32 RSP, +40 SS. */
    .globl pf_stub
pf_stub:
    testb $3, 16(%rsp)
    jz 9f
    swapgs
9:
    push %rax
    push %rcx
    push %rdx
    push %rsi
    push %rdi
    push %r8
    push %r9
    push %r10
    push %r11
    /* 9 pushes put the hardware frame at 72(%rsp): err 72,
     * rip 80, cs 88, rsp 104. pf_info takes 40 more bytes,
     * shifting those offsets by 40 for the reads below. */
    sub $40, %rsp
    mov %cr2, %rax
    mov %rax, 0(%rsp)
    mov 112(%rsp), %rax
    mov %rax, 8(%rsp)
    mov 120(%rsp), %rax
    mov %rax, 16(%rsp)
    mov 128(%rsp), %rax
    mov %rax, 24(%rsp)
    mov 144(%rsp), %rax
    mov %rax, 32(%rsp)
    mov %rsp, %rdi
    call yousj_page_fault
    add $40, %rsp
    /* Canonicalize a ring-3 frame's selectors, exactly as
     * irq0_stub does: a task resumed by sysret runs with
     * QEMU's fabricated CS=0x1B / SS=0x13, and iretq rejects
     * that pair with #GP. The hardware frame is at 72(%rsp)
     * here (err 72, rip 80, cs 88, ss 112); the user-window
     * test keeps kernel frames out of the rewrite. %rax is
     * still scratch -- the saved user %rax pops later. */
    movq $0x8000000000, %rax     /* YOUSJ_USER_BASE */
    cmpq %rax, 80(%rsp)
    jb 7f
    movq $0x8003000000, %rax     /* YOUSJ_USER_LIMIT */
    cmpq %rax, 80(%rsp)
    jae 7f
    movq $0x23, 88(%rsp)
    movq $0x1B, 112(%rsp)
7:
    pop %r11
    pop %r10
    pop %r9
    pop %r8
    pop %rdi
    pop %rsi
    pop %rdx
    pop %rcx
    pop %rax
    testb $3, 16(%rsp)
    jz 8f
    swapgs
8:
    add $8, %rsp
    iretq

    .globl irq0_stub
irq0_stub:
    /* GS discipline (M7): the syscall path's swapgs pairing only
     * stays sound if EVERY kernel context runs with the kernel
     * GS base. A ring-3 frame arrives with the user's base (0),
     * and sched_tick() may switch straight from here to a task
     * that is blocked inside a syscall -- that task's exit path
     * dereferences %gs and would fault on the stranded user
     * base (this exact crash, a #PF on `mov %r11,%gs:8`, is
     * what M7's spinning-child scenario first produced). So:
     * swap on the way in when the interrupted frame is ring 3,
     * swap back before iretq to ring 3; ring-0 frames never
     * swap. The decision reads the interrupted CS's RPL bits
     * (hardware frame: [rsp]=RIP, [rsp+8]=CS at entry; the same
     * test after the pops sees the canonicalized CS, whose RPL
     * the canonicalization never changes). If the task blocks
     * or exits inside this frame, the swap stays outstanding on
     * its own stack -- balanced when (if) it resumes here. */
    testb $3, 8(%rsp)
    jz 9f
    swapgs
9:
    push %rax
    push %rcx
    push %rdx
    push %rsi
    push %rdi
    push %r8
    push %r9
    push %r10
    push %r11
    call irq0_handler
    /* M79: the return path below is shared with the generic
     * IRQ stubs (irq_stub_1..15): they enter with the same
     * register state irq0_stub has at this point (9 saved
     * registers above the hardware frame) and jump here
     * after calling irq_dispatch(). */
irq_return:
    /* Canonicalize a ring-3 frame's selectors before iretq.
     * QEMU's sysret derives CS/SS from the wrong STAR field,
     * so a task resumed from a syscall runs in ring 3 with
     * CS=0x1B / SS=0x13 (fabricated caches) and a timer frame
     * captured there fails iretq's GDT checks. If the frame's
     * RIP lies in the user window, rewrite CS/SS to the
     * canonical user pair; on silicon the frame already holds
     * them and this is a no-op. The window test must be exact:
     * since M6 the kernel itself executes at 0xFFFFFFFF80000000+
     * and kernel stacks live in the HHDM, both far ABOVE the
     * window -- a bare "RIP >= user base" test would misread
     * every kernel frame as a user frame and iretq into ring 3
     * (this exact bug halted the first M6 boot). The hardware
     * frame lies above the 9 saved registers: RIP at +72, CS
     * at +80, SS at +104 from here. */
    movq $0x8000000000, %rax     /* YOUSJ_USER_BASE */
    cmpq %rax, 72(%rsp)
    jb 1f
    movq $0x8003000000, %rax     /* YOUSJ_USER_LIMIT */
    cmpq %rax, 72(%rsp)
    jae 1f
    movq $0x23, 80(%rsp)
    movq $0x1B, 104(%rsp)
    jmp 2f
1:
    /* Kernel frame: heal QEMU's swapped-field syscall artifact
     * (CS=0x10 / SS=0x18, from its [47:32] entry load) to the
     * canonical kernel pair. On silicon a kernel frame already
     * holds 0x08/0x10 and this never triggers. */
    cmpq $0x10, 80(%rsp)
    jne 2f
    cmpq $0x18, 104(%rsp)
    jne 2f
    movq $0x08, 80(%rsp)
    movq $0x10, 104(%rsp)
2:
    /* Signal delivery gate (M7): hand signal_irq_check() the
     * interrupted context. The callee-saved registers were never
     * saved by this stub (the C handler chain preserves them,
     * so they still hold the interrupted values); push them now
     * -- 48 bytes, a multiple of 16, so the C call alignment is
     * the same as at the irq0_handler call above. Pieces:
     *   rdi = the 9 saved registers ([0]=r11 ... [8]=rax)
     *   rsi = the hardware frame (rip, cs, rflags, rsp, ss)
     *   rdx = the 6 pushes just made ([0]=r15 ... [40]=rbx )
     * signal_irq_check() itself decides whether the frame is a
     * ring-3 frame of a user task with anything to deliver; in
     * the common case it returns immediately. It may rewrite
     * the frame to enter a signal handler, block the task
     * (stop), or exit it (fatal signal). */
    push %rbx
    push %rbp
    push %r12
    push %r13
    push %r14
    push %r15
    lea 48(%rsp), %rdi
    lea 120(%rsp), %rsi
    mov %rsp, %rdx
    call signal_irq_check
    pop %r15
    pop %r14
    pop %r13
    pop %r12
    pop %rbp
    pop %rbx
    pop %r11
    pop %r10
    pop %r9
    pop %r8
    pop %rdi
    pop %rsi
    pop %rdx
    pop %rcx
    pop %rax
    testb $3, 8(%rsp)       /* returning to ring 3: swap back */
    jz 9f
    swapgs
9:
    iretq

    /* Generic IRQ stubs (M79): one per PIC line 1..15.
     * Entry mirrors irq0_stub exactly (GS discipline, the
     * same 9 caller-saved registers), the line number goes
     * to irq_dispatch() in %edi, and the shared irq_return
     * above handles canonicalization, the signal gate and
     * the iretq. Devices register through irq_register();
     * until then every line stays masked in the PIC. */
    .macro IRQ_STUB n
    .globl irq_stub_\n
irq_stub_\n:
    testb $3, 8(%rsp)
    jz 9f
    swapgs
9:
    push %rax
    push %rcx
    push %rdx
    push %rsi
    push %rdi
    push %r8
    push %r9
    push %r10
    push %r11
    mov $\n, %edi
    call irq_dispatch
    jmp irq_return
    .endm

    .set i, 1
    .rept 15
    IRQ_STUB %i
    .set i, i+1
    .endr

    .section .rodata
    .globl irq_stub_table
irq_stub_table:
    .quad irq0_stub
    .quad irq_stub_1
    .quad irq_stub_2
    .quad irq_stub_3
    .quad irq_stub_4
    .quad irq_stub_5
    .quad irq_stub_6
    .quad irq_stub_7
    .quad irq_stub_8
    .quad irq_stub_9
    .quad irq_stub_10
    .quad irq_stub_11
    .quad irq_stub_12
    .quad irq_stub_13
    .quad irq_stub_14
    .quad irq_stub_15
    .globl exc_table
exc_table:
    .macro EXC_REF i
    .quad exc_stub_\i
    .endm
    .set i, 0
    .rept 32
    EXC_REF %i
    .set i, i+1
    .endr

    .section .note.GNU-stack, "", @progbits

